function validate([nums1, nums2]) {
  for (const [name, nums] of [['nums1', nums1], ['nums2', nums2]]) {
    if (!Array.isArray(nums) || nums.length < 1 || nums.length > 1000) return `${name} needs 1 to 1000 values.`;
    if (nums.some(v => !Number.isInteger(v) || v < 0 || v > 1000)) return `Each value in ${name} is a whole number from 0 to 1000.`;
  }
  return null;
}

