function intersection(nums1, nums2) {
  const common = [];
  for (let i = 0; i < nums1.length; i++) {
    let inSecond = false;
    for (let j = 0; j < nums2.length; j++) if (nums2[j] === nums1[i]) inSecond = true;
    let already = false;
    for (let k = 0; k < common.length; k++) if (common[k] === nums1[i]) already = true;
    if (inSecond && !already) common.push(nums1[i]);
  }
  return common;
}

