function generate(rand, size) {
  const pick = k => Math.floor(rand() * k);
  if (size === 'large') {
    const span = rand() < 0.5 ? 1001 : 50 + pick(500);
    const offset = pick(1001 - span + 1);
    const make = () => Array.from({ length: 800 + pick(201) }, () => offset + pick(span));
    return [make(), make()];
  }
  const span = 1 + pick(10);
  const offset = rand() < 0.2 ? 1000 - span + 1 : rand() < 0.3 ? 0 : pick(990);
  const make = () => Array.from({ length: 1 + pick(7) }, () => offset + pick(span));
  return [make(), make()];
}
